zh:
// 信号是多少就出多少。
// 出价最高的人，手里是全场最乐观的那个估计：平均每次买贵 ε(N−1)/(N+1)。
function decide(s, p) {
  return s.x;
}

en:
// Bid exactly the signal.
// The highest bidder holds the most optimistic estimate in the market: on average it overpays by ε(N−1)/(N+1) each time.
function decide(s, p) {
  return s.x;
}

zh:
// 假如我的估计是全场最高的，V 平均比它低 ε(N−1)/(N+1)。让掉这一截，买到手的时候平均不赚不亏。
function decide(s, p) {
  return s.x - s.g.eps * (s.n - 1) / (s.n + 1);
}

en:
// If my estimate is the highest in the market, V is on average ε(N−1)/(N+1) below it. Shading by this much, I break even on average when I win.
function decide(s, p) {
  return s.x - s.g.eps * (s.n - 1) / (s.n + 1);
}

zh:
// 风险中性的对称均衡。
// 第一价格：x − ε + Y，Y = 2ε/(N+1)·exp(−N(x − lo − ε)/(2ε))；信号比 lo + ε 还低时是 lo + (x + ε − lo)/(N+1)。
// 第二价格：x − ε(N−2)/N（假如第二高的估计和我的一样，V 的期望值）。
// 信号贴近上边界 hi 时这只是近似。
function decide(s, p) {
  var g = s.g, n = s.n, e = g.eps;
  if (g.fmt === "second") return s.x - e * (n - 2) / n;
  if (s.x < g.lo + e) return g.lo + (s.x + e - g.lo) / (n + 1);
  return s.x - e + 2 * e / (n + 1) * Math.exp(-n * (s.x - g.lo - e) / (2 * e));
}

en:
// The risk-neutral symmetric equilibrium.
// First price: x − ε + Y, Y = 2ε/(N+1)·exp(−N(x − lo − ε)/(2ε)); when the signal is below lo + ε it is lo + (x + ε − lo)/(N+1).
// Second price: x − ε(N−2)/N (the expected value of V if the second-highest estimate equals mine).
// Near the upper boundary hi this is only an approximation.
function decide(s, p) {
  var g = s.g, n = s.n, e = g.eps;
  if (g.fmt === "second") return s.x - e * (n - 2) / n;
  if (s.x < g.lo + e) return g.lo + (s.x + e - g.lo) / (n + 1);
  return s.x - e + 2 * e / (n + 1) * Math.exp(-n * (s.x - g.lo - e) / (2 * e));
}

zh:
// 每次都比自己的估计少出 d。d 太小会中赢家诅咒，太大又总是买不到。
function decide(s, p) {
  return s.x - p.d;
}

en:
// Always bid d below my own estimate. Too small a d falls for the winner's curse; too large a d never wins.
function decide(s, p) {
  return s.x - p.d;
}

zh:
// 从盈亏里学让价 d。
// 上一回合买到了而且亏了：d 加 up。连着 wait 个回合没买到：d 减 down。
function init(p) {
  return { d: p.d0, dry: 0 };
}
function decide(s, p, st) {
  if (s.t > 0) {
    if (s.won) { st.dry = 0; if (s.last < 0) st.d += p.up; }
    else if (++st.dry >= p.wait) { st.dry = 0; st.d = Math.max(0, st.d - p.down); }
  }
  return s.x - st.d;
}

en:
// Learn the shading d from the P&L.
// Won the previous round and lost money: d increases by up. No win for wait rounds in a row: d decreases by down.
function init(p) {
  return { d: p.d0, dry: 0 };
}
function decide(s, p, st) {
  if (s.t > 0) {
    if (s.won) { st.dry = 0; if (s.last < 0) st.d += p.up; }
    else if (++st.dry >= p.wait) { st.dry = 0; st.d = Math.max(0, st.d - p.down); }
  }
  return s.x - st.d;
}

zh:
// 卖价 = x + h，买价 = x − h。
// h 小：总能抢到单，但抢到的多半是自己估错的那些。h 大：安全，可是没人找你成交。
function decide(s, p) {
  return p.h;
}

en:
// Ask = x + h, bid = x − h.
// Small h: you always win the trade, but mostly the ones where your estimate was off. Large h: safe, but no one trades with you.
function decide(s, p) {
  return p.h;
}

zh:
// 卖价全场最低的那条规则，手里是最悲观的估计：V 平均比它高 ε(N−1)/(N+1)。
// 半价差取这么大，卖给不知情的客人平均不赚不亏；碰上知情的客人还是要亏。
function decide(s, p) {
  return s.g.eps * (s.n - 1) / (s.n + 1);
}

en:
// The rule with the lowest ask in the market holds the most pessimistic estimate: V is on average ε(N−1)/(N+1) above it.
// With a half-spread this large, selling to uninformed customers breaks even on average; against informed customers it still loses.
function decide(s, p) {
  return s.g.eps * (s.n - 1) / (s.n + 1);
}

zh:
// 在保本价差上再加 m。知情的客人越多（s.g.pi 越大），m 就该越大。
function decide(s, p) {
  return s.g.eps * (s.n - 1) / (s.n + 1) + p.m;
}

en:
// Add m on top of the break-even spread. The more informed customers there are (the larger s.g.pi), the larger m should be.
function decide(s, p) {
  return s.g.eps * (s.n - 1) / (s.n + 1) + p.m;
}

